#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>

#define MAX_FRAME_SIZE 4096
#define MAX_CLIENTS 64
#define ROLE_GUEST 0
#define ROLE_USER 1
#define ROLE_ADMIN 2

typedef struct {
    int fd;
    uint8_t role;
    char username[32];
    uint8_t handler_id;
} client_session;

typedef struct {
    client_session clients[MAX_CLIENTS];
    int num_clients;
    char server_key[64];
} ws_server;

static ws_server g_server;

typedef void (*cmd_handler_fn)(client_session*, const char*, size_t);

void handle_admin_cmd(client_session *sess, const char *payload, size_t len) {
    char response[256];
    snprintf(response, sizeof(response), "Admin ACK: %.200s", payload);
    send(sess->fd, response, strlen(response), 0);
}

void handle_user_cmd(client_session *sess, const char *payload, size_t len) {
    char response[128];
    snprintf(response, sizeof(response), "User ACK: %.100s", payload);
    send(sess->fd, response, strlen(response), 0);
}

void handle_guest_cmd(client_session *sess, const char *payload, size_t len) {
    const char *response = "Guest: read-only access";
    send(sess->fd, response, strlen(response), 0);
}

static const cmd_handler_fn handler_table[3] = {
    handle_guest_cmd,
    handle_user_cmd,
    handle_admin_cmd
};

static int validate_frame_header(const uint8_t *buf, size_t buflen, uint64_t *payload_len) {
    if (buflen < 2) return -1;
    uint8_t opcode = buf[0] & 0x0F;
    uint8_t masked = (buf[1] & 0x80) != 0;
    uint64_t len = buf[1] & 0x7F;
    size_t header_size = 2;

    if (len == 126) {
        if (buflen < 4) return -1;
        len = ((uint64_t)buf[2] << 8) | buf[3];
        header_size = 4;
    } else if (len == 127) {
        if (buflen < 10) return -1;
        len = 0;
        for (int i = 0; i < 8; i++)
            len = (len << 8) | buf[2 + i];
        header_size = 10;
    }

    if (masked) header_size += 4;
    *payload_len = len;
    return (int)header_size;
}

static void dispatch_message(client_session *sess, const uint8_t *frame, size_t frame_len) {
    uint64_t payload_len;
    int header_size = validate_frame_header(frame, frame_len, &payload_len);
    if (header_size < 0) return;

    /* Role-based size enforcement */
    size_t max_allowed;
    switch (sess->role) {
        case ROLE_ADMIN: max_allowed = 2048; break;
        case ROLE_USER:  max_allowed = 512;  break;
        default:         max_allowed = 128;  break;
    }

    if (payload_len > max_allowed) {
        const char *err = "Message exceeds role limit";
        send(sess->fd, err, strlen(err), 0);
        return;
    }

    /* Validate payload doesn't exceed frame bounds */
    if ((size_t)header_size + (size_t)payload_len > frame_len) {
        return;
    }

    /* Unmask and copy payload to stack buffer for processing */
    char payload_buf[2048];
    uint8_t mask_key[4];

    if (frame[1] & 0x80) {
        int mask_offset = header_size - 4;
        if (mask_offset < 2 || mask_offset + 4 > (int)frame_len) return;
        memcpy(mask_key, &frame[mask_offset], 4);
        size_t copy_len = (size_t)payload_len;
        if (copy_len > sizeof(payload_buf) - 1) return;
        memcpy(payload_buf, &frame[header_size], copy_len);
        for (size_t i = 0; i < copy_len; i++)
            payload_buf[i] ^= mask_key[i % 4];
    } else {
        size_t copy_len = (size_t)payload_len;
        if (copy_len > sizeof(payload_buf) - 1) return;
        memcpy(payload_buf, &frame[header_size], copy_len);
    }

    payload_buf[payload_len] = '\0';

    /* Invoke role-specific handler via validated index into table */
    if (sess->handler_id <= ROLE_ADMIN)
        handler_table[sess->handler_id](sess, payload_buf, (size_t)payload_len);
}

static int upgrade_role(client_session *sess, const char *token, size_t token_len) {
    /* Simplified token validation */
    char computed[64];

    if (token_len > 60) return 0; /* Strict bound */

    /* Stack-based HMAC-like computation */
    char workbuf[128];
    memset(workbuf, 0, sizeof(workbuf));
    memcpy(workbuf, g_server.server_key, 64);
    memcpy(workbuf + 64, token, token_len);

    /* Simple hash for demo */
    uint32_t hash = 0x811c9dc5;
    for (size_t i = 0; i < 64 + token_len; i++) {
        hash ^= (uint8_t)workbuf[i];
        hash *= 0x01000193;
    }

    snprintf(computed, sizeof(computed), "%08x", hash);

    if (strcmp(computed, "deadbeef") == 0) {
        sess->role = ROLE_ADMIN;
        sess->handler_id = ROLE_ADMIN;
        return 1;
    }
    return 0;
}

static void process_control_frame(client_session *sess, const uint8_t *frame, size_t len) {
    uint64_t payload_len;
    int header_size = validate_frame_header(frame, len, &payload_len);
    if (header_size < 0) return;

    uint8_t opcode = frame[0] & 0x0F;

    if (opcode == 0x09) { /* Ping */
        uint8_t pong[128];
        pong[0] = 0x8A;
        if (payload_len <= 125 && (size_t)header_size + payload_len <= len) {
            pong[1] = (uint8_t)payload_len;
            memcpy(&pong[2], &frame[header_size], (size_t)payload_len);
            send(sess->fd, pong, 2 + payload_len, 0);
        }
    }
}

static void handle_connection(int client_fd) {
    client_session sess;
    memset(&sess, 0, sizeof(sess));
    sess.fd = client_fd;
    sess.role = ROLE_GUEST;
    sess.handler_id = ROLE_GUEST;
    strncpy(sess.username, "anonymous", sizeof(sess.username) - 1);

    uint8_t recv_buf[MAX_FRAME_SIZE];

    while (1) {
        ssize_t n = recv(client_fd, recv_buf, sizeof(recv_buf), 0);
        if (n <= 0) break;

        uint8_t opcode = recv_buf[0] & 0x0F;

        if (opcode >= 0x08) {
            if (opcode == 0x08) break; /* Close */
            process_control_frame(&sess, recv_buf, (size_t)n);
        } else {
            /* Check for role upgrade request */
            uint64_t plen;
            int hs = validate_frame_header(recv_buf, (size_t)n, &plen);
            if (hs > 0 && plen > 8 && (size_t)hs + plen <= (size_t)n) {
                char peek[9];
                memcpy(peek, &recv_buf[hs], 8);
                peek[8] = '\0';
                if (strcmp(peek, "UPGRADE:") == 0) {
                    size_t tlen = (size_t)plen - 8;
                    if (tlen < 61) {
                        char token_buf[64];
                        memcpy(token_buf, &recv_buf[hs + 8], tlen);
                        token_buf[tlen] = '\0';
                        upgrade_role(&sess, token_buf, tlen);
                    }
                    continue;
                }
            }
            dispatch_message(&sess, recv_buf, (size_t)n);
        }
    }
    close(client_fd);
}

int main(int argc, char *argv[]) {
    memset(&g_server, 0, sizeof(g_server));
    strncpy(g_server.server_key, "s3cr3t_k3y_f0r_hmac_validation_do_not_share!!", 63);

    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) { perror("socket"); return 1; }
    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
    struct sockaddr_in addr = {.sin_family = AF_INET, .sin_port = htons(9001), .sin_addr.s_addr = INADDR_ANY};
    if (bind(server_fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) { perror("bind"); return 1; }
    listen(server_fd, 10);

    printf("WebSocket server listening on :9001\n");
    while (1) {
        int client_fd = accept(server_fd, NULL, NULL);
        if (client_fd >= 0)
            handle_connection(client_fd);
    }
    return 0;
}
